P3para.Text:
in subsections (1) and (7) for “the 1986 Act” substitute “
                        the Companies Act 1985
                      ”;

in sections 55(4)(a)

							(orders to make material available) and 56(3)(a) and (4)(a)

							(authority for search) the words “or has benefited from”;

for “county court” substitute “
                      Crown Court
                    ”;

in sub-paragraph (a) for the words from “an investigation” to the end of head (ii) substitute “
                      a confiscation investigation
                    ”;

after “application made by” insert “
                      the Director of the Assets Recovery Agency or
                    ”;

for “county court” substitute “
                      Crown Court
                    ”;

in sub-paragraph (a) for the words from “an investigation” to the end of head (ii) substitute “
                      a confiscation investigation
                    ”;

in sub-paragraph (b) after “if” insert “
                      the Director or
                    ”;

after “authorise” insert “
                      the Director or
                    ”;

in sub-paragraph (1) for “any conduct to which Article 49 applies” substitute “
                      his criminal conduct
                    ”;
